drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · translate failures and always dispose★★☆ core
//  concepts: custom exceptions · inner exceptions · using
// ─────────────────────────────────────────────────────────────────────────
//
//  Translate what callers can act on, propagate the rest, release resources on every path.

using static Bootcamp.Check;

Order LoadOrder(int id, Func<int, Order?> fetch)
{
    Order? order;
    try
    {
        order = fetch(id);
    }
    catch (TimeoutException ex)
    {
        throw new StoreUnavailableException("orders store unavailable", ex);
    }
    return order ?? throw new NotFoundException($"Order {id} was not found");
}

int CountLines(Func<TextReader> open)
{
    using var reader = open();
    var count = 0;
    while (reader.ReadLine() is not null) count++;
    return count;
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a missing order is a NotFoundException", () =>
{
    var ex = Throws<NotFoundException>(() => LoadOrder(42, _ => null));
    Eq(ex.Message, "Order 42 was not found");
});

Test("a timeout is translated and kept as the inner exception", () =>
{
    var timeout = new TimeoutException("db timeout");
    var ex = Throws<StoreUnavailableException>(() => LoadOrder(1, _ => throw timeout));
    Ok(ReferenceEquals(ex.InnerException, timeout), "InnerException must be the original timeout");
});

Test("other exceptions propagate unchanged", () =>
{
    var boom = new InvalidOperationException("bug");
    var ex = Throws<InvalidOperationException>(() => LoadOrder(1, _ => throw boom));
    Ok(ReferenceEquals(ex, boom), "the same exception object");
});

Test("CountLines counts and disposes", () =>
{
    var reader = new TrackingReader("a\nb\nc");
    Eq(CountLines(() => reader), 3);
    Ok(reader.Disposed, "the reader was not disposed");
});

Test("the reader is disposed when reading throws", () =>
{
    var reader = new TrackingReader("a\nb", failAfter: 1);
    Throws<IOException>(() => CountLines(() => reader));
    Ok(reader.Disposed, "the reader was not disposed after the failure");
});

Test("an empty reader has zero lines (boundary)", () =>
    Eq(CountLines(() => new TrackingReader("")), 0));

