// ──────────────────────────── types ──────────────────────────────────────

record Order(int Id, decimal Total);

class NotFoundException(string message) : Exception(message);

class StoreUnavailableException(string message, Exception inner) : Exception(message, inner);

class TrackingReader(string text, int failAfter = int.MaxValue) : StringReader(text)
{
    private int _reads;
    public bool Disposed { get; private set; }
    public override string? ReadLine()
    {
        if (_reads++ >= failAfter) throw new IOException("disk read failed");
        return base.ReadLine();
    }
    protected override void Dispose(bool disposing)
    {
        Disposed = true;
        base.Dispose(disposing);
    }
}

drills.explanation:
Catch only the exception you translate, and keep the rest of the method outside the try so nothing else is caught by accident:

```csharp
try { order = fetch(id); }
catch (TimeoutException ex) { throw new StoreUnavailableException("orders store unavailable", ex); }
return order ?? throw new NotFoundException($"Order {id} was not found");
```

Passing `ex` to the constructor keeps the timeout as `InnerException`. `using var reader = open();` disposes the reader on success and on the IOException alike, because the declaration compiles to a try/finally. Widening the clause to `catch (Exception ex)` turns the InvalidOperationException into a StoreUnavailableException and fails "other exceptions propagate unchanged". Calling `reader.Dispose()` after the loop without a try/finally fails "the reader is disposed when reading throws": the IOException skips that call.

